/**
 * Inter, the same typeface as the site, embedded as base64.
 *
 * **Not read from disk, and not fetched, and both were tried first.**
 *
 * `fetch(new URL("./x.ttf", import.meta.url))` is the pattern the Next docs
 * show for this. It works in the edge runtime and throws
 * "not implemented... yet..." in the node runtime, because node's fetch has no
 * `file:` support. Reading with `fs` works locally and then depends on the
 * file surviving deployment tracing, which fails in production and nowhere
 * else, which is the worst place to find out.
 *
 * A string cannot be left behind by a bundler. It costs about 180 KB in the
 * repository and nothing at request time, since the buffers are decoded once
 * per instance.
 *
 * Two weights, not five. The badge uses 500, 600, 700 and 800; the renderer
 * maps each to the nearest it has, so 600 and 800 cover all four without
 * carrying two more files for differences nobody can see at this size.
 *
 * Inter is under the SIL Open Font License, which permits redistribution.
 * Regenerate with the block at the bottom of this file's history if the
 * typeface is ever updated.
 */

const INTER_600 =
  "";

const INTER_800 =
  "";

import { mkdirSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";

let cache: string[] | null = null;

/**
 * Paths to the two font files, written out on first use.
 *
 * The rasteriser takes file paths, not buffers, in this version. So the bytes
 * live in this file as strings, which survives any bundler, and are written to
 * the machine's temp directory the first time a badge is drawn. Temp is
 * writable on the platform this deploys to, the write happens once per
 * instance, and if the files are already there it does nothing.
 *
 * The alternative was keeping two `.ttf` files in the repository and trusting
 * deployment tracing to carry them. That works locally every time and fails in
 * production silently, which is the worst way round.
 */
export function interFontFiles(): string[] {
  if (cache) return cache;

  const dir = join(tmpdir(), "aim-badge-fonts-v1");
  mkdirSync(dir, { recursive: true });

  const files = [
    { path: join(dir, "Inter-600.ttf"), b64: INTER_600 },
    { path: join(dir, "Inter-800.ttf"), b64: INTER_800 },
  ];

  for (const f of files) {
    if (!existsSync(f.path)) {
      writeFileSync(f.path, Buffer.from(f.b64, "base64"));
    }
  }

  cache = files.map((f) => f.path);
  return cache;
}
